#include <bits/stdc++.h>
using namespace std;
class Solution {int m,n;vector<vector<int>> memo;vector<vector<int>>* a;int dfs(int r,int c){if(memo[r][c])return memo[r][c];const int M=1000000007;long long ans=1;int dr[]={1,-1,0,0},dc[]={0,0,1,-1};for(int z=0;z<4;++z){int x=r+dr[z],y=c+dc[z];if(x>=0&&x<m&&y>=0&&y<n&&(*a)[x][y]>(*a)[r][c])ans+=dfs(x,y);}return memo[r][c]=ans%M;}public:int countPaths(vector<vector<int>>& grid){a=&grid;m=grid.size();n=grid[0].size();memo.assign(m,vector<int>(n));long long ans=0;for(int i=0;i<m;++i)for(int j=0;j<n;++j)ans+=dfs(i,j);return ans%1000000007;}};
